cat > vm.py <<'EOF'
# tiny stack VM. PROG is a flat int stream of opcodes+operands.
# 0 PUSH imm | 1 ADD | 2 XOR | 3 EMIT(pop->char) | 4 DUP | 5 MUL | 6 HALT
PROG = [0, 28, 0, 90, 2, 3, 0, 22, 0, 90, 2, 3, 0, 27, 0, 90, 2, 3, 0, 29, 0, 90, 2, 3, 0, 33, 0, 90, 2, 3, 0, 41, 0, 90, 2, 3, 0, 46, 0, 90, 2, 3, 0, 110, 0, 90, 2, 3, 0, 57, 0, 90, 2, 3, 0, 49, 0, 90, 2, 3, 0, 5, 0, 90, 2, 3, 0, 46, 0, 90, 2, 3, 0, 40, 0, 90, 2, 3, 0, 59, 0, 90, 2, 3, 0, 57, 0, 90, 2, 3, 0, 63, 0, 90, 2, 3, 0, 39, 0, 90, 2, 3, 6]
def run(prog):
    st = []; out = []; i = 0
    while i < len(prog):
        op = prog[i]; i += 1
        if op == 0:
            st.append(prog[i]); i += 1
        elif op == 1:
            b = st.pop(); a = st.pop(); st.append((a + b) & 0xff)
        elif op == 2:
            b = st.pop(); a = st.pop(); st.append(a ^ b)
        elif op == 3:
            out.append(chr(st.pop()))
        elif op == 4:
            st.append(st[-1])
        elif op == 5:
            b = st.pop(); a = st.pop(); st.append((a * b) & 0xff)
        elif op == 6:
            break
    return ''.join(out)

if __name__ == '__main__':
    print(run(PROG))
EOF

