set -e
cat > lic.py <<'EOF'
def _h(name):
    h = 0
    for c in name:
        h = (h * 31 + ord(c)) & 0xffffffff
    return h

def validate(name, serial):
    h = _h(name)
    expect = "%04X-%04X" % ((h >> 16) & 0xffff, h & 0xffff)
    return serial == expect
EOF

