# flattened control flow: one dispatch loop over `state`.
def f(n):
    state = 0; acc = 0; x = n
    while True:
        if state == 0:
            acc = x + 7; state = 3
        elif state == 3:
            acc = acc ^ 0x2a; state = 1
        elif state == 1:
            state = 2 if acc % 2 == 0 else 4
        elif state == 2:
            acc = (acc * 3) & 0xffff; state = 5
        elif state == 4:
            acc = (acc + 100) & 0xffff; state = 5
        elif state == 5:
