#!/usr/bin/env bash
set -e
cat > vm.js <<'EOF'
// stack VM. PROG is a flat int stream.
// 0 PUSH imm | 1 ADD | 2 XOR | 3 EMIT | 6 HALT
const PROG = [0, 117, 0, 51, 2, 3, 0, 127, 0, 51, 2, 3, 0, 114, 0, 51, 2, 3, 0, 116, 0, 51, 2, 3, 0, 72, 0, 51, 2, 3, 0, 89, 0, 51, 2, 3, 0, 64, 0, 51, 2, 3, 0, 108, 0, 51, 2, 3, 0, 69, 0, 51, 2, 3, 0, 94, 0, 51, 2, 3, 0, 108, 0, 51, 2, 3, 0, 92, 0, 51, 2, 3, 0, 88, 0, 51, 2, 3, 0, 78, 0, 51, 2, 3, 6];
function run(p) {
  let st = [], out = [], i = 0;
  while (i < p.length) {
    let op = p[i++];
    if (op === 0) { st.push(p[i++]); }
    else if (op === 1) { let b = st.pop(), a = st.pop(); st.push((a + b) & 0xff); }
    else if (op === 2) { let b = st.pop(), a = st.pop(); st.push(a ^ b); }
    else if (op === 3) { out.push(String.fromCharCode(st.pop())); }
    else if (op === 6) { break; }
  }
  return out.join('');
}
console.log(run(PROG));
EOF

#!/usr/bin/env bash
set -e
cat > check.js <<'EOF'
function valid(s) {
  if (!/^[0-9]{4}$/.test(s)) return false;
  const d = [...s].map(Number);
  if (d[0] + d[1] + d[2] + d[3] !== 20) return false;
  if (d[0] !== d[3]) return false;
  if (d[1] * d[2] !== 15) return false;
  return true;
}
const s = process.argv[2] || "";
console.log(valid(s) ? "OK" : "NO");
EOF

